        "crabswarm",
        "chat",
        "report-state"
      ]
    },
    "requireEnv": {
      "type": "string",
      "multiple": true,
      "title": "Required environment",
      "description": "Variable names. The mod runs only when the session's environment sets at least one of them. Empty always runs.",
      "default": [
        "CRABSWARM_CHAT_TOKEN",
        "CMDMAN_CMD_ID"
      ]
    }
  }
}
